mapper.select:
SELECT language_code, title, summary, eligibility, deadline_text, method_text, notice
FROM JL_PROCEDURE_I18N
WHERE procedure_id = #{procedureId}

mapper.update:
UPDATE JL_PROCEDURE_I18N
SET title = #{title}, summary = #{summary}, eligibility = #{eligibility},
    deadline_text = #{deadline}, method_text = #{method}, notice = #{notice}
WHERE procedure_id = #{procedureId} AND language_code = #{lang}

mapper.select:
SELECT language_code, name, condition_text
FROM JL_DOCUMENT_I18N
WHERE document_id = #{documentId}

mapper.update:
UPDATE JL_DOCUMENT_I18N
SET name = #{name}, condition_text = #{conditionText}
WHERE document_id = #{documentId} AND language_code = #{lang}

UPDATE JL_DOCUMENT
SET procedure_id = #{procedureId}, name = #{name}, requirement = #{requirement},
    condition_text = #{conditionText}, display_order = #{displayOrder}
WHERE id = #{id}

UPDATE JL_STEP
SET procedure_id = #{procedureId}, step_no = #{stepNo}, title = #{title}, description = #{description}
WHERE id = #{id}

UPDATE JL_SOURCE
SET procedure_id = #{procedureId}, title = #{title}, url = #{url}, checked_on = #{checkedOn}, updated_on = #{updatedOn}
WHERE id = #{id}

UPDATE JL_OFFICE
SET name = #{name}, address = #{address}, homepage_url = #{homepageUrl}, note = #{note}
WHERE id = #{id}
